  "inlineSchema": "// Prisma Schema for WebBanHoaQua E-commerce\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ===================== ENUM DEFINITIONS =====================\n\n// Role Enum\nenum Role {\n  ADMIN\n  USER\n}\n\n// Order Status Enum\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  SHIPPING\n  COMPLETED\n  CANCELLED\n}\n\n// Payment Status Enum\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\n// Payment Method Enum\nenum PaymentMethod {\n  COD\n  BANK_TRANSFER\n  MOMO\n  ZALOPAY\n}\n\n// User Status Enum\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  LOCKED\n}\n\n// ===================== USER MODEL =====================\nmodel User {\n  id        String     @id @default(uuid())\n  email     String     @unique\n  password  String\n  fullName  String\n  phone     String?\n  address   String?\n  avatar    String?\n  role      Role       @default(USER)\n  status    UserStatus @default(ACTIVE)\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  // Relations\n  carts   Cart[]\n  orders  Order[]\n  reviews Review[]\n\n  @@map(\"users\")\n}\n\n// ===================== CATEGORY MODEL =====================\nmodel Category {\n  id          String   @id @default(uuid())\n  name        String\n  slug        String?  @unique\n  description String?  @db.Text\n  image       String?\n  parentId    String?\n  isActive    Boolean  @default(true)\n  sortOrder   Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Self-referential for parent-child categories\n  parent   Category?  @relation(\"CategoryRelation\", fields: [parentId], references: [id])\n  children Category[] @relation(\"CategoryRelation\")\n\n  // Relations\n  products Product[]\n\n  @@map(\"categories\")\n}\n\n// ===================== PRODUCT MODEL =====================\nmodel Product {\n  id            String   @id @default(uuid())\n  name          String\n  slug          String   @unique\n  description   String?  @db.Text\n  price         Decimal  @db.Decimal(12, 2)\n  originalPrice Decimal? @db.Decimal(12, 2)\n  unit          String   @default(\"kg\") // kg, cái, túi, hộp...\n  stock         Int      @default(0)\n  sku           String?  @unique\n  isFeatured    Boolean  @default(false)\n  isActive      Boolean  @default(true)\n  viewCount     Int      @default(0)\n  soldCount     Int      @default(0)\n  rating        Decimal  @default(0) @db.Decimal(3, 2)\n  reviewCount   Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Relations\n  categoryId String\n  category   Category       @relation(fields: [categoryId], references: [id])\n  images     ProductImage[]\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n  reviews    Review[]\n  faqs       ChatbotFAQ[]\n\n  @@map(\"products\")\n}\n\n// ===================== PRODUCT IMAGE MODEL =====================\nmodel ProductImage {\n  id        String   @id @default(uuid())\n  productId String\n  url       String\n  altText   String?\n  isPrimary Boolean  @default(false)\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n\n  // Relations\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@map(\"product_images\")\n}\n\n// ===================== CART MODEL =====================\nmodel Cart {\n  id        String   @id @default(uuid())\n  userId    String?  @unique\n  sessionId String?  @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user  User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  items CartItem[]\n\n  @@map(\"carts\")\n}\n\n// ===================== CART ITEM MODEL =====================\nmodel CartItem {\n  id        String   @id @default(uuid())\n  cartId    String\n  productId String\n  quantity  Int      @default(1)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  cart    Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([cartId, productId])\n  @@map(\"cart_items\")\n}\n\n// ===================== ORDER MODEL =====================\nmodel Order {\n  id              String        @id @default(uuid())\n  orderNumber     String        @unique\n  userId          String\n  status          OrderStatus   @default(PENDING)\n  subtotal        Decimal       @db.Decimal(12, 2)\n  shippingFee     Decimal       @default(0) @db.Decimal(12, 2)\n  discount        Decimal       @default(0) @db.Decimal(12, 2)\n  total           Decimal       @db.Decimal(12, 2)\n  shippingName    String\n  shippingPhone   String\n  shippingAddress String        @db.Text\n  shippingNote    String?       @db.Text\n  paymentMethod   PaymentMethod @default(COD)\n  paymentStatus   PaymentStatus @default(PENDING)\n  confirmedAt     DateTime?\n  shippedAt       DateTime?\n  completedAt     DateTime?\n  cancelledAt     DateTime?\n  cancelReason    String?       @db.Text\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  user    User        @relation(fields: [userId], references: [id])\n  items   OrderItem[]\n  payment Payment?\n\n  @@map(\"orders\")\n}\n\n// ===================== ORDER ITEM MODEL =====================\nmodel OrderItem {\n  id           String   @id @default(uuid())\n  orderId      String\n  productId    String\n  productName  String\n  productImage String?\n  quantity     Int\n  price        Decimal  @db.Decimal(12, 2)\n  total        Decimal  @db.Decimal(12, 2)\n  createdAt    DateTime @default(now())\n\n  // Relations\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@map(\"order_items\")\n}\n\n// ===================== PAYMENT MODEL =====================\nmodel Payment {\n  id            String        @id @default(uuid())\n  orderId       String        @unique\n  method        PaymentMethod\n  amount        Decimal       @db.Decimal(12, 2)\n  status        PaymentStatus @default(PENDING)\n  transactionId String?\n  paymentData   String?       @db.Text\n  paidAt        DateTime?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  // Relations\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  @@map(\"payments\")\n}\n\n// ===================== REVIEW MODEL =====================\nmodel Review {\n  id        String   @id @default(uuid())\n  userId    String\n  productId String\n  rating    Int\n  comment   String?  @db.Text\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user    User    @relation(fields: [userId], references: [id])\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId])\n  @@map(\"reviews\")\n}\n\n// ===================== CHATBOT FAQ MODEL =====================\nmodel ChatbotFAQ {\n  id        String   @id @default(uuid())\n  question  String   @db.Text\n  answer    String   @db.Text\n  keywords  String?  @db.Text\n  category  String? // product, order, general, price, shipping\n  isActive  Boolean  @default(true)\n  priority  Int      @default(0)\n  productId String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  product Product? @relation(fields: [productId], references: [id], onDelete: SetNull)\n\n  @@map(\"chatbot_faqs\")\n}\n\n// ===================== SYSTEM SETTING MODEL =====================\nmodel SystemSetting {\n  id            String   @id\n  siteName      String   @default(\"WebBanHoaQua\")\n  contactEmail  String?\n  contactPhone  String?\n  address       String?  @db.Text\n  businessHours String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@map(\"system_settings\")\n}\n",
